/**
 * Final test for comment stripping functionality
 * This JSDoc should be preserved with --keep-docs
 */

// eslint-disable-next-line no-console
function processData(input) {
    // Regular comment to remove
    const result = {
        data: input,
        processed: true,
        message: "Processing complete", // Trailing comment
        timestamp: new Date().toISOString()
    };
    
    /* 
     * Multi-line comment
     * Should be removed
     */
    
    // @important: This is critical
    if (input === null) {
        // WARNING: Null input detected
        return {
            error: "Invalid input",
            success: false
        };
    }
    
    return result; // Return processed data
}

export default processData;

